import itertools

n = 23
fixed_seq = {5: -1, 10: -1, 13: 1, 19: 1}
fixed_c = {12: 0, 13: -3, 16: 0, 19: -1}

def get_c(seq, k):
    return sum(seq[i] * seq[i+k] for i in range(n - k))

def solve():
    # Indices of unfixed bits
    unfixed = [i for i in range(n) if i not in fixed_seq]

    for p in itertools.product([-1, 1], repeat=len(unfixed)):
        seq = [0] * n
        for i, val in fixed_seq.items():
            seq[i] = val
        for i, val in zip(unfixed, p):
            seq[i] = val

        # Check fixed C_k
        valid = True
        for k, expected_c in fixed_c.items():
            if get_c(seq, k) != expected_c:
                valid = False
                break
        if not valid:
            continue

        # Check sum of C_k^2
        sum_sq = 0
        for k in range(1, n):
            c_k = get_c(seq, k)
            sum_sq += c_k * c_k
            if sum_sq > 59:
                valid = False
                break

        if valid:
            print("Found:", seq)
            return seq

    print("UNSATISFIABLE")
    return None

solve()

